CREATE TABLE tabc(a,b,c); INSERT INTO tabc VALUES(1,2,3); CREATE TABLE txyz(x,y,z); INSERT INTO txyz VALUES(4,5,6); CREATE TABLE tboth(a,b,c,x,y,z); INSERT INTO tboth VALUES(11,12,13,14,15,16); CREATE VIEW v4(a,x,"a:1","x:1","a:2",b,c,"x:2",y,z,"a:3","b:1","c:1","x:3","y:1","z:1") AS SELECT tabc.a,txyz.x,tboth.a,tboth.x,tabc.a,tabc.b,tabc.c,txyz.x,txyz.y,txyz.z,tboth.a,tboth.b,tboth.c,tboth.x,tboth.y,tboth.z FROM tabc,txyz,tboth;